import {Selection} from "prosemirror-state"
import * as browser from "./browser"
import {domIndex, selectionCollapsed, parentNode,
        DOMSelectionRange, DOMNode, isText, isElt} from "./dom"
import {hasFocusAndSelection, selectionFromDOM} from "./selection"
import {EditorView} from "./index"
import {readDOMChange} from "./domchange"
import {Damage, TextViewDesc, ViewDesc} from "./viewdesc"

const observeOptions = {
  childList: true,
  characterData: true,
  characterDataOldValue: true,
  attributes: true,
  attributeOldValue: true,
  subtree: true
}

export class DOMObserver {
  queue: MutationRecord[] = []
  flushingSoon = -1
  observer: MutationObserver
  suppressingSelectionUpdates = false
  lastChangedTextNode: Text | null = null
  started = false

  constructor(readonly view: EditorView) {
    this.observer = new window.MutationObserver(mutations => {
      for (let i = 0; i < mutations.length; i++) this.queue.push(mutations[i])
      if (browser.safari && view.composing && mutations.some(
        m => m.type == "childList" && m.target.nodeName == "TR")) {
        // Safari does weird stuff when finishing a composition in a
        // table cell, which tends to involve inserting inappropriate
        // nodes in the table row.
        view.input.badSafariComposition = true
        this.flushSoon()
      } else {
        this.flush()
      }
    })
  }

  flushSoon() {
    if (this.flushingSoon < 0)
      this.flushingSoon = window.setTimeout(() => { this.flushingSoon = -1; this.flush() }, 20)
  }

  forceFlush(always = false) {
    if (this.flushingSoon > -1) {
      window.clearTimeout(this.flushingSoon)
      this.flushingSoon = -1
      this.flush(true)
    } else if (always) {
      this.flush(true)
    }
  }

  start() {
    this.observer.takeRecords()
    this.observer.observe(this.view.dom, observeOptions)
    this.started = true
  }

  stop() {
    let take = this.observer.takeRecords()
    if (take.length) {
      for (let i = 0; i < take.length; i++) this.queue.push(take[i])
      window.setTimeout(() => this.flush(), 20)
    }
    this.observer.disconnect()
    this.started = false
  }

  stopped<T>(f: () => T): T {
    if (!this.started) return f()
    this.stop()
    try { return f() }
    finally { this.start() }
  }

  ignoreSelectionChange(sel: DOMSelectionRange) {
    if (!sel.focusNode) return true
    let ancestors: Set<Node> = new Set, container: DOMNode | undefined
    for (let scan: DOMNode | null = sel.focusNode; scan; scan = parentNode(scan)) ancestors.add(scan)
    for (let scan = sel.anchorNode; scan; scan = parentNode(scan)) if (ancestors.has(scan)) {
      container = scan
      break
    }
    let desc = container && this.view.docView.nearestDesc(container)
    if (desc && desc.ignoreMutation({
      type: "selection",
      target: isText(container!) ? container!.parentNode! : container!
    })) {
      this.view.domSel.ignore(sel)
      return true
    }
  }

  pendingRecords() {
    for (let mut of this.observer.takeRecords()) this.queue.push(mut)
    return this.queue
  }

  flush(readSel = true) {
    let {view} = this
    if (!view.docView || this.flushingSoon > -1) return
    let mutations = this.pendingRecords()
    if (mutations.length) this.queue = []
    if (readSel) view.domSel.read()

    let selChange = !view.domSel.suppress && !view.domSel.synced && !!hasFocusAndSelection(view) &&
      !this.ignoreSelectionChange(view.domSel.range)

    let from = -1, to = -1, typeOver = false, added: Node[] = []
    if (view.editable) {
      for (let i = 0; i < mutations.length; i++) {
        let result = this.registerMutation(mutations[i], added)
        if (result) {
          from = from < 0 ? result.from : Math.min(result.from, from)
          to = to < 0 ? result.to : Math.max(result.to, to)
          if (result.typeOver) typeOver = true
        }
      }
    }

    if (added.some(n => n.nodeName == "BR") &&
        (view.input.lastKeyCode == 8 || view.input.lastKeyCode == 46 ||
         browser.chrome && (view.composing || view.input.compositionEndedAt > Date.now() - 50) &&
         mutations.some(m => m.type == "childList" && m.removedNodes.length))) {
      // Browsers sometimes insert a bogus break node if you
      // backspace out the last bit of text before an inline-flex node (#1552)
      for (let node of added) if (node.nodeName == "BR" && node.parentNode) {
        let after = node.nextSibling
        while (after && isElt(after)) {
          if (after.contentEditable == "false") {
            node.parentNode.removeChild(node)
            break
          }
          after = after.firstChild
        }
      }
    } else if (browser.gecko && added.length) {
      let brs = added.filter(n => n.nodeName == "BR") as HTMLElement[]
      if (brs.length == 2) {
        let [a, b] = brs
        if (a.parentNode && a.parentNode.parentNode == b.parentNode) b.remove()
        else a.remove()
      } else {
        let {focusNode} = view.domSel.range
        for (let br of brs) {
          let parent = br.parentNode
          if (parent && parent.nodeName == "LI" && (!focusNode || blockParent(view, focusNode) != parent))
            br.remove()
        }
      }
    }

    let newSel: Selection | null = null
    // If it looks like the browser has reset the selection to the
    // start of the document after focus, restore the selection from
    // the state
    if (from < 0 && selChange && view.domSel.active && view.input.lastFocus > Date.now() - 200 &&
        Math.max(view.input.lastTouch, view.input.lastClick.time) < Date.now() - 300 &&
        selectionCollapsed(view.domSel.range) && (newSel = selectionFromDOM(view, view.domSel.range)) &&
        newSel.eq(Selection.near(view.state.doc.resolve(0), 1))) {
      view.input.lastFocus = 0
      view.domSel.sync()
      view.scrollToSelection()
    } else if (from > -1 || selChange) {
      if (from > -1) checkCSS(view)
      if (view.input.badSafariComposition) {
        view.input.badSafariComposition = false
        fixUpBadSafariComposition(view, added)
      }
      readDOMChange(this.view, from, to, selChange, typeOver, added)
      if (view.docView && view.docView.damage) view.updateState(view.state)
      else if (selChange) view.domSel.sync()
    }
  }

  registerMutation(mut: MutationRecord, added: Node[]) {
    // Ignore mutations inside nodes that were already noted as inserted
    if (added.indexOf(mut.target) > -1) return null
    let desc: ViewDesc | undefined
    for (let scan: DOMNode | null = mut.target; scan; scan = scan.parentNode) {
      if (desc = this.view.docView.getDesc(scan)) break
    }
    if (mut.type == "attributes" &&
        (desc == this.view.docView || mut.attributeName == "contenteditable" ||
         // Firefox sometimes fires spurious events for null/empty styles
         (mut.attributeName == "style" && !mut.oldValue && !(mut.target as HTMLElement).getAttribute("style"))))
      return null
    if (!desc || desc.ignoreMutation(mut)) return null

    if (mut.type == "childList") {
      for (let i = 0; i < mut.addedNodes.length; i++) {
        let node = mut.addedNodes[i]
        added.push(node)
        if (isText(node)) this.lastChangedTextNode = node
      }
      if (desc.contentDOM && desc.contentDOM != desc.dom && !desc.contentDOM.contains(mut.target)) {
        desc.markDamage(Damage.Structure)
        return {from: desc.posBefore, to: desc.posAfter}
      }
      let prev = mut.previousSibling, next = mut.nextSibling
      let fromOffset = prev && prev.parentNode == mut.target
          ? domIndex(prev) + 1 : 0
      let from = desc.localPosFromDOM(mut.target, fromOffset, -1)
      let toOffset = next && next.parentNode == mut.target
          ? domIndex(next) : mut.target.childNodes.length
      let to = desc.localPosFromDOM(mut.target, toOffset, 1)
      desc.markDamage(desc.contentDOM?.contains(mut.target) ? Damage.ChildList : Damage.Structure)
      return {from, to}
    } else if (mut.type == "attributes") {
      desc.markDamage(Damage.Structure)
      return {from: desc.posAtStart - desc.border, to: desc.posAtEnd + desc.border}
    } else { // "characterData"
      this.lastChangedTextNode = mut.target as Text
      desc.markDamage(desc instanceof TextViewDesc && mut.target == desc.nodeDOM ? Damage.Text : Damage.Structure)
      return {
        from: desc.posAtStart,
        to: desc.posAtEnd,
        // An event was generated for a text change that didn't change
        // any text. Mark the dom change to fall back to assuming the
        // selection was typed over with an identical value if it can't
        // find another change.
        typeOver: mut.target.nodeValue == mut.oldValue
      }
    }
  }
}

let cssChecked: WeakMap<EditorView, null> = new WeakMap()
let cssCheckWarned: boolean = false

function checkCSS(view: EditorView) {
  if (cssChecked.has(view)) return
  cssChecked.set(view, null)
  if (['normal', 'nowrap', 'pre-line'].indexOf(getComputedStyle(view.dom).whiteSpace) !== -1) {
    view.requiresGeckoHackNode = browser.gecko
    if (cssCheckWarned) return
    console["warn"]("ProseMirror expects the CSS white-space property to be set, preferably to 'pre-wrap'. It is recommended to load style/prosemirror.css from the prosemirror-view package.")
    cssCheckWarned = true
  }
}

function blockParent(view: EditorView, node: DOMNode): Node | null {
  for (let p = node.parentNode; p && p != view.dom; p = p.parentNode) {
    let desc = view.docView.nearestDesc(p, true)
    if (desc && desc.node.isBlock) return p
  }
  return null
}

// Kludge for a Safari bug where, on ending a composition in an
// otherwise empty table cell, it randomly moves the composed text
// into the table row around that cell, greatly confusing everything
// (#188).
function fixUpBadSafariComposition(view: EditorView, addedNodes: readonly DOMNode[]) {
  let {focusNode, focusOffset} = view.domSel.range
  for (let node of addedNodes) {
    if (node.parentNode?.nodeName == "TR") {
      let nextCell = node.nextSibling
      while (nextCell && (nextCell.nodeName != "TD" && nextCell.nodeName != "TH")) nextCell = nextCell.nextSibling
      if (nextCell) {
        let parent = nextCell
        for (;;) {
          let first = parent.firstChild
          if (!first || !isElt(first) || first.contentEditable == "false" || /^(BR|IMG)$/.test(first.nodeName)) break
          parent = first
        }
        parent.insertBefore(node, parent.firstChild)
        if (focusNode == node) view.domSelection()!.collapse(node, focusOffset)
      } else {
        node.parentNode.removeChild(node)
      }
    }
  }
}
